<?php
require_once __DIR__.'/config/conexion.php';
$modulos=['clientes'=>['Clientes','Personas registradas'],'proveedores'=>['Proveedores','Contactos de suministro'],'articulos'=>['Artículos','Catálogo e inventario'],'facturas'=>['Facturación','Ventas registradas']];
$conteos=[];foreach($modulos as $t=>$d)$conteos[$t]=(int)$pdo->query("SELECT COUNT(*) FROM $t WHERE eliminado_en IS NULL")->fetchColumn();
$totalVentas=(float)$pdo->query("SELECT COALESCE(SUM(total),0) FROM facturas WHERE eliminado_en IS NULL")->fetchColumn();
$totalPapelera=(int)$pdo->query("SELECT (SELECT COUNT(*) FROM clientes WHERE eliminado_en IS NOT NULL)+(SELECT COUNT(*) FROM proveedores WHERE eliminado_en IS NOT NULL)+(SELECT COUNT(*) FROM articulos WHERE eliminado_en IS NOT NULL)+(SELECT COUNT(*) FROM facturas WHERE eliminado_en IS NOT NULL)")->fetchColumn();
$movimientos=$pdo->query("SELECT tipo,tabla_afectada,descripcion,fecha FROM movimientos ORDER BY fecha DESC,id DESC LIMIT 7")->fetchAll();
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
?>
<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Centro de gestión | Ferretería</title><link rel="stylesheet" href="assets/estilos.css"></head><body class="admin-body">
<header class="admin-top"><a class="marca" href="administracion.php">FERRETERÍA <span> / CENTRO DE GESTIÓN</span></a><div><a href="reportes.php">Reportes</a><a href="papelera.php">Papelera (<?= $totalPapelera ?>)</a><a href="index.php">Ver sitio ↗</a></div></header>
<main class="admin-dashboard"><div class="admin-welcome"><div><p class="sobrelinea">PANEL DE CONTROL / <?= date('d.m.Y') ?></p><h1>Centro de gestión.</h1><p>Inventario, registros y actividad de la ferretería en un solo lugar.</p></div><a class="admin-primary-link" href="modulo.php?tabla=articulos">Gestionar inventario <span>→</span></a></div>
<div class="dashboard-stats"><article><span>VENTAS REGISTRADAS</span><strong>$<?= number_format($totalVentas,2) ?></strong><small>MXN · acumulado</small></article><?php foreach($modulos as $t=>$d):?><article><span><?= strtoupper(h($d[0])) ?></span><strong><?= $conteos[$t] ?></strong><small><?= h($d[1]) ?></small></article><?php endforeach;?></div>
<div class="dashboard-section-heading"><div><p class="sobrelinea">ÁREAS DE TRABAJO</p><h2>Administrar información</h2></div><span>01 / MÓDULOS</span></div>
<div class="admin-module-grid"><?php foreach($modulos as $tabla=>$datos):?><a href="modulo.php?tabla=<?= h($tabla) ?>" class="admin-module"><span class="module-number"><?= str_pad((string)(array_search($tabla,array_keys($modulos))+1),2,'0',STR_PAD_LEFT) ?></span><div><h3><?= h($datos[0]) ?></h3><p><?= h($datos[1]) ?></p></div><strong><?= $conteos[$tabla] ?></strong><span class="module-arrow">↗</span></a><?php endforeach;?></div>
<div class="dashboard-lower"><section class="admin-card"><div class="admin-card-head"><div><p class="sobrelinea">SEGUIMIENTO</p><h2>Actividad reciente</h2></div><a class="admin-inline-link" href="reportes.php">Ver reportes →</a></div><?php if(!$movimientos):?><p class="admin-empty">Aún no hay movimientos. Las altas, modificaciones y envíos a papelera aparecerán aquí.</p><?php endif;?><?php foreach($movimientos as $m):?><div class="activity-row"><span class="activity-dot"></span><div><strong><?= h($m['tipo']) ?> · <?= h($m['tabla_afectada']) ?></strong><p><?= h($m['descripcion']) ?></p></div><time><?= h($m['fecha']) ?></time></div><?php endforeach;?></section><section class="admin-card admin-trash-card"><p class="sobrelinea">RECUPERACIÓN</p><h2>Papelera</h2><strong><?= $totalPapelera ?></strong><p>Registros retirados que todavía puedes recuperar.</p><a class="admin-inline-link" href="papelera.php">Revisar papelera →</a></section></div>
<footer class="admin-footer">Sistema de gestión · PHP + MySQL · Ferretería</footer></main></body></html>